cat > /tmp/mk.mjs <<'E'
import fs from 'fs';import cp from 'child_process';
const root=cp.execSync('git rev-parse --show-toplevel').toString().trim();
const dir=root+'/people/angelo/pipeline';
const files=['ROLES.md','QUEUE.md',...fs.readdirSync(dir+'/skills').filter(f=>f.endsWith('.md')).map(f=>'skills/'+f),...fs.readdirSync(dir+'/formats').filter(f=>f.endsWith('.md')).map(f=>'formats/'+f)];
const re=/[A-Za-z0-9_.@{}<>*-]+(\/[A-Za-z0-9_.@{}<>*-]+)+\/?|[A-Za-z0-9_-]+\.(md|json|mjs|js|sh|png|yml|txt|html)/g;
const jobFiles=new Set(['STATE.md','brief.md','build.md','check.md','design.md','draft.md','go.md','post.md','publish.md','research.md','sources.md','times.json','runs.md','digest.md','accounts.md','lanes.json','release.sh','SKILL.md','conductor.md','pool-claim.mjs']);
const m=new Map();
for(const f of files){const t=fs.readFileSync(dir+'/'+f,'utf8');for(let p of t.match(re)||[]){
 p=p.replace(/[.,]+$/,'');
 if(/[{}<>*]/.test(p)||/^(https?|origin|claude|project|PrompTugal|SGit-AI|creativecommons|ws-trace|pki\.sgit|\.sg-send)/.test(p)||p.includes('creativecommons'))continue;
 if(!p.includes('/')&&jobFiles.has(p))continue;
 if(p.startsWith('pool/')||p==='pki-agent.mjs'&&false)continue;
 (m.get(p)||m.set(p,new Set()).get(p)).add(f);}}
const paths=[...m].sort().map(([p,s])=>({path:p,exists:fs.existsSync(root+'/'+p),named_in:[...s].sort()}));
fs.writeFileSync(root+'/paths.json',JSON.stringify({count:paths.length,paths},null,2)+'\n');
console.log(paths.length);
for(const x of paths)console.log(x.exists,x.path);
E
node /tmp/mk.mjs
